import React from 'react';

const DiceNumber = ({ number = 0, id = 1 }) => {
    const digitContainerStyle = {
        position: 'relative',
        float: 'left',
        width: '2.06vw',
        height: '5vh',
        overflow: 'hidden'
    };

    const digitStyle = {
        position: 'absolute',
        width: '2.06vw',
        height: '55vh'
    };

    const numberString = number.toString().padStart(7, '0');
    
    return (
        <div id={`jackpot${id}`}>
            <div className="digit-space" style={{...digitContainerStyle, width: '1.03vw'}} />
            {numberString.split('').map((digit, index) => (
                <div key={`jackpot${id}-digit${index}`} id={`jackpot${id}-digit${index}`} style={digitContainerStyle}>
                    <div 
                        className="digit" 
                        id={`jackpot${id}-digit-bg${index}`} 
                        style={{
                            ...digitStyle, 
                            top: `-${parseInt(digit) * 5}vh`
                        }} 
                    />
                </div>
            ))}
            <div style={{clear: 'both'}} />
        </div>
    );
};

export default DiceNumber;

