import React from 'react';
import mainBackground from '../assets/img/themes/bg_panoramic.jpg';
import logo from '../assets/img/themes/logo.png';
import Banner from './Banner';
import MobileBanner from './MobileBanner';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { Navigation, Pagination, Mousewheel, Keyboard } from 'swiper/modules';
import frame from '../assets/img/themes/frame.png';
import dragon from '../assets/img/dragonkingdomicon.jpg';
import leftArrow from '../assets/img/themes/leftarrow.png';
import rightArrow from '../assets/img/themes/rightarrow.png';

const GridItem = ({ image = dragon }) => (
    <div className="relative">
        <div className="absolute inset-0 bg-cover bg-center bg-no-repeat rounded-[20px]" style={{ backgroundImage: `url(${dragon})` }}>
            <img src={frame} alt="dragon" />
        </div>
    </div>
);

const generateGridItems = (count = 8, image = frame) =>
    Array.from({ length: count }, (_, i) => <GridItem key={i} image={image} />);

const MainContent = () => {
    const slides = [
        { id: 1, content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 sm:px-12 lg:px-24 py-8 h-full mx-[30px]">{generateGridItems()}</div> },
        { id: 2, content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 sm:px-12 lg:px-24 py-8 h-full mx-[50px]">{generateGridItems()}</div> },
        { id: 3, content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 sm:px-12 lg:px-24 py-8 h-full mx-[50px]">{generateGridItems()}</div> },
        { id: 4, content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 sm:px-12 lg:px-24 py-8 h-full mx-[50px]">{generateGridItems()}</div> },
    ];

    return (
        <main className="relative flex flex-col w-full h-[calc(100vh)] lg:h-[calc(100vh-62px)] overflow-hidden">
            <div
                className="absolute inset-0 w-full h-full animate-zoomEffect"
                style={{
                    backgroundImage: `url(${mainBackground})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat'
                }}
            />
            <div className="relative z-10">
                <Banner className="hidden lg:flex" />
                <div className="hidden sm:flex sm:flex-col w-full items-center">
                    <img src={logo} alt="logo" className="w-[42%] h-[7.6rem] mt-[-10px] mb-[10px]" />
                </div>
                <Banner className="hidden sm:flex lg:hidden" />
                <MobileBanner />
            </div>

            <div className="pt-[48px] h-[58.7%]">
                <Swiper
                    cssMode={true}
                    navigation={{
                        nextEl: '.swiper-button-next',
                        prevEl: '.swiper-button-prev',
                    }}
                    pagination={true}
                    mousewheel={true}
                    keyboard={true}
                    loop={true}
                    modules={[Navigation, Pagination, Mousewheel, Keyboard]}
                    className="mySwiper h-full [&_.swiper-button-next:after]:hidden [&_.swiper-button-prev:after]:hidden [&_.swiper-button-next]:w-[7%] [&_.swiper-button-prev]:w-[7%] [&_.swiper-button-next]:h-[7rem] [&_.swiper-button-prev]:h-[7rem] [&_.swiper-button-next]:bg-contain [&_.swiper-button-prev]:bg-contain [&_.swiper-button-next]:bg-no-repeat [&_.swiper-button-prev]:bg-no-repeat [&_.swiper-button-next]:bg-center [&_.swiper-button-prev]:bg-center [&_.swiper-button-next]:right-0 [&_.swiper-button-prev]:left-0 [&_.swiper-button-next]:top-1/2 [&_.swiper-button-prev]:top-1/2 [&_.swiper-button-next]:-translate-y-1/2 [&_.swiper-button-prev]:-translate-y-1/2"
                >
                    {slides.map(slide => (
                        <SwiperSlide key={slide.id}>
                            {slide.content}
                        </SwiperSlide>
                    ))}
                    <div className="swiper-button-prev bg-contain bg-no-repeat bg-center" style={{ backgroundImage: `url(${leftArrow})` }}></div>
                    <div className="swiper-button-next bg-contain bg-no-repeat bg-center" style={{ backgroundImage: `url(${rightArrow})` }}></div>
                </Swiper>
            </div>
        </main>
    );
};

export default MainContent;
