import React, { useState } from 'react';
import enFlag from '../assets/img/flag/en.png';
import esFlag from '../assets/img/flag/es.png';
import layoutImg from '../assets/img/temp/layout_8.png';

const Footer = () => {
    const [imgHeight, setImgHeight] = useState(40);

    const handleClick = () => {
        setImgHeight(50);
    };

    const handleMouseLeave = () => {
        setImgHeight(40);
    };

    return (
        <footer className='hidden sm:flex absolute bottom-0 left-0 right-0 z-[100]'>
            <div className="flex flex-col pt-2 pr-2 w-[21.5%] text-white font-bold relative
                before:absolute before:inset-0 before:rounded-tr-[10px] before:bg-gradient-to-r before:from-[#6921bc] before:via-[#e8b3ff] before:to-[#943bf8] before:-z-10">
                                
                <div className="flex flex-col pb-[8px] items-center justify-end w-[99%] h-[125px] rounded-tr-[10px] text-white font-bold relative bg-[#601eae] shadow-[inset_0_0_10px_rgba(0,0,0,0.5)] shadow-[inset_0_0_10px_rgb(0 0 0 / 100%)]">
                    <div className='flex w-full h-[53.7px] items-center justify-center'>
                        <div className='flex flex-col w-[66.5%] cursor-pointer items-center justify-center h-full'>
                            <span className='text-[35px] text-cashbackFt font-normal font-["Impact"]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>BALANCE</span>
                        </div>
                        <div className='flex w-[33.5%] justify-between h-full'>
                            <button onClick={handleClick} onMouseLeave={handleMouseLeave}><img src={enFlag} alt="English" className={`cursor-pointer w-[40px] h-[${imgHeight}px] rounded-full`} /></button>
                            <button><img src={layoutImg} alt="Layout" className='cursor-pointer w-[40px] h-[40px]' /></button>
                        </div>
                    </div>
                    
                    <div className='flex w-full h-[68.7px] mr-[2px] shadow-[0_0_5px_rgba(0,0,0,0.6)] shadow-[0_0_5px_rgb(0 0 0 / 1)]'>
                        <div className='flex flex-col w-[40%] lg:w-[66.5%] cursor-pointer items-center justify-center'>
                            <span className='text-[32px] font-normal font-["Impact"]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>8161</span>
                        </div>
                        <div className='flex w-[60%] lg:w-[33.5%] h-full flex-col justify-center bg-cashbackBg rounded-[4px]'>
                            <p className="text-[10px] text-center text-cashbacktx font-normal font-impact cursor-pointer" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>CASHBACK BONUS</p>
                            <p className="text-[25px] text-center font-normal font-impact cursor-pointer" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>1560</p>
                        </div>
                    </div>
                </div>
            </div>
            
            
        </footer>
    );
};

export default Footer;
